{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall ensure compliance with data protection regulations while maintaining historical attendance data for a minimum of five years using energy-efficient storage practices.",
      "quality_axes": ["Safety|Efficiency|Sustainability|Trustworthiness|Responsibility"],
      "derived_from": ["SAF-04", "RES-07", "EFF-04", "GRN-02"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall provide real-time attendance data processing with a response time of no more than three seconds.",
      "quality_axes": ["Efficiency|Safety"],
      "derived_from": ["EFF-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-03",
      "text": "The system shall ensure secure authentication and data encryption to protect sensitive student information.",
      "quality_axes": ["Safety|Trustworthiness"],
      "derived_from": ["SAF-01", "TRU-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-04",
      "text": "The system shall provide role-based access control to restrict data access based on user roles.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-02", "RES-06"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-05",
      "text": "The system shall allow students to view their attendance records after successful authentication and within a defined timeframe.",
      "quality_axes": ["Trustworthiness|Efficiency"],
      "derived_from": ["TRU-04"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-06",
      "text": "The system shall generate attendance reports in formats that minimize resource usage.",
      "quality_axes": ["Sustainability|Efficiency"],
      "derived_from": ["GRN-04"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-07",
      "text": "The system shall maintain a logging mechanism for all attendance modifications to support accountability.",
      "quality_axes": ["Trustworthiness|Safety"],
      "derived_from": ["SAF-05", "TRU-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-08",
      "text": "The system shall implement automated alerts for discrepancies in attendance reporting.",
      "quality_axes": ["Safety|Trustworthiness"],
      "derived_from": ["SAF-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-09",
      "text": "The system shall notify users of their carbon footprint based on attendance patterns.",
      "quality_axes": ["Sustainability|Responsibility"],
      "derived_from": ["GRN-05"],
      "kaos_level": "operational",
      "parent": null
    }
  ],
